def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Opening sequence: Cooperate, then tit-for-tat style with retaliation
    if n <= 2:
        return 'C'

    # Count defections by opponent
    opp_def = 0
    my_def = 0
    for i in range(n):
        my, opp = history[i]
        if opp == 'D':
            opp_def += 1
        if my == 'D':
            my_def += 1

    # If opponent has never defected, cooperate (be nice)
    if opp_def == 0:
        return 'C'

    # If opponent defected last round, retaliate
    last_my, last_opp = history[-1]
    if last_opp == 'D':
        return 'D'

    # If opponent is mostly cooperative, cooperate
    if opp_def <= n // 5:
        return 'C'

    # If opponent defects frequently, defect more
    if opp_def > n // 3:
        # Check if we should try to re-establish cooperation
        # If opponent cooperated last round after defecting, encourage it
        if last_opp == 'C' and n >= 5:
            # Check the last few rounds
            recent_coops = 0
            check = min(3, n)
            for i in range(n - check, n):
                if history[i][1] == 'C':
                    recent_coops += 1
            if recent_coops >= 2:
                return 'C'
        return 'D'

    # Moderate opponent defection - play tit-for-tat with some forgiveness
    # Check if opponent is in a cooperative streak
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_c += 1
        else:
            break

    if streak_c >= 2:
        return 'C'

    # If we've been defecting a lot and opponent is retaliating, try to reset
    my_recent_def = 0
    check = min(3, n)
    for i in range(n - check, n):
        if history[i][0] == 'D':
            my_recent_def += 1

    if my_recent_def >= 2 and last_opp == 'D':
        # Try a peace offering occasionally
        if rng.random() < 0.3:
            return 'C'

    # Default: mirror opponent's last move (tit-for-tat)
    return last_opp

